script:
(function () {
  if (window.__evx) return; window.__evx = true;
  var APP = "<!DOCTYPE html>
<html lang="ka"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">
<title>Meeting Room Pad</title>
<style>
@font-face{font-family:'PingGeL';src:url(data:font/woff2;base64,) format('woff2');font-weight:300;font-display:swap}
@font-face{font-family:'PingGeL';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'PingGeL';src:url(data:font/woff2;base64,) format('woff2');font-weight:500;font-display:swap}
@font-face{font-family:'PingGeL';src:url(data:font/woff2;base64,) format('woff2');font-weight:700;font-display:swap}
:root{--coral:#FA6E5F;--ink:#303030;--paper:#F9F9F9;--teal:#148380;--red:#E8344D;--font:'PingGeL',system-ui,sans-serif}
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;user-select:none}
html,body{height:100%;overflow:hidden;background:#222;font-family:var(--font);color:var(--ink)}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer}
button{transition:scale .12s}button:active{scale:.96}
.rb:active{scale:1}.rb img{transition:scale .15s cubic-bezier(.2,.8,.3,1)}.rb:active img{scale:.78}
#stage{position:absolute;left:0;top:0;width:1280px;height:800px;transform-origin:0 0;overflow:hidden;
background:#FBFBFB}
#frame{position:absolute;left:calc((100% - 1280px)/2);top:calc((100% - 800px)/2);width:1280px;height:800px}
#bg{position:absolute;inset:0;overflow:hidden;pointer-events:none}
#dim{position:absolute;inset:0;background:#0B0E16;opacity:0;transition:opacity .7s ease}
.blob{position:absolute;background:radial-gradient(closest-side,var(--c),transparent 70%);animation:drift calc(var(--d) * .9) ease-in-out infinite;will-change:transform}
@keyframes drift{0%{transform:translate(0,0) scale(1)}35%{transform:translate(var(--x),var(--y)) scale(var(--s))}70%{transform:translate(calc(var(--x) * -.5),calc(var(--y) * -.6)) scale(.92)}100%{transform:translate(0,0) scale(1)}}
.a{position:absolute}.page{position:absolute;inset:0;display:none}.page.on{display:block}
.mid{transform:translateY(-50%)}
/* logo */
.logo{width:153px;height:auto;display:block}
.hdr{left:85px;top:36px;display:flex;align-items:center;gap:16px;height:46px}
.hdr b{font-size:32px;font-weight:700}.hdr u{width:1px;height:42px;background:var(--ink)}
/* home */
.rule{height:1px;background:var(--ink)}
.badge{color:#fff;left:90px;top:352px;height:32px;padding:0 15px;border:1px solid var(--ink);border-radius:6px;background:var(--coral);font-size:15px;display:flex;align-items:center}
.badge.free{background:var(--teal);color:#fff;border-color:var(--teal)}
/* side panel */
#side{position:absolute;right:0;top:0;height:100%;width:71px;background:var(--coral);border-radius:32px 0 0 32px;box-shadow:-10px 0 30px rgba(0,0,0,.28);transition:width .3s ease;overflow:hidden;color:#fff;z-index:5}
#side.full,#side.open{width:407px}
#side>.in{position:absolute;right:0;top:0;width:407px;height:100%;display:none}
#side.full>.f,#side.open>.p{display:block}
#side.full.open>.p{display:none}
.sbtn{position:absolute;right:20px;top:20px;width:34px;height:34px;display:grid;place-items:center}
#clock,#clock2{left:0;right:0;top:70px;text-align:center;font-size:92px;font-weight:300;line-height:1.1}
#sdate,#sdate2{left:0;right:0;top:182px;text-align:center;font-size:24px}
#side .ln{left:48px;right:48px;top:235px;height:1px;background:rgba(255,255,255,.8)}
#sideList{left:48px;right:48px;top:261px;bottom:48px;overflow-y:auto;scrollbar-width:none}
#sideList::-webkit-scrollbar{display:none}
.sc{height:99px;margin-bottom:25px;border:1px solid #fff;border-radius:12px;padding:16px 18px;position:relative}
.sc h4{font-size:22px;font-weight:600;line-height:1.2}.sc p{font-size:15px}.sc small{font-size:13px;display:block}
.sc em{position:absolute;right:18px;top:20px;font-style:normal;font-size:13px}
#sdate2{top:56px;font-size:26px;font-weight:400}#sdate2 b{font-weight:700}
#wIcon{left:123px;top:118px;width:160px;height:160px}
#wTemp{left:0;right:0;top:308px;text-align:center;font-size:52px;font-weight:300;line-height:62px}
#wCond{left:0;right:0;top:374px;text-align:center;font-size:17px;line-height:22px}
#wInfo{left:56px;top:425px;width:294px;height:24px;display:flex;flex-direction:row;align-items:center;gap:46px;font-size:15px}
#wInfo span{display:flex;align-items:center;gap:6px;white-space:nowrap}#wInfo i{font-style:normal}
#wInfo svg,.pb svg{width:24px;height:24px;stroke:#fff;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
#fc{left:56px;right:0;top:496px;height:142px;display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x proximity;scrollbar-width:none;padding:15px 56px 15px 0}
#fc::-webkit-scrollbar{display:none}
.fd{flex:none;width:74px;height:112px;border-radius:13px;background:rgba(110,60,55,.5);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;scroll-snap-align:start;font-size:14px}
.fd .wi{width:38px;height:38px}.fd b{font-size:17px;font-weight:300}
.wi img{width:100%;height:100%;object-fit:contain;display:block}
#pBtns{left:56px;bottom:40px;width:295px;display:flex;justify-content:space-between}
.pb,.mb{display:flex;align-items:center;justify-content:center;gap:6px;flex:none;width:136px;height:34px;background:rgba(110,60,55,.5);border-radius:10px;color:#fff;font-size:13px;white-space:nowrap}
.mb{font-size:15px}.pb svg,.pb img{width:20px;height:20px}
#wInfo img{height:24px;width:auto;display:block}
#ov{position:absolute;inset:0;display:grid;place-items:center;z-index:20;pointer-events:none;visibility:hidden;transition:visibility 0s .35s}
#ov.on{pointer-events:auto;visibility:visible;transition:none}
#ov:before{content:"";position:absolute;inset:0;background:#000;opacity:0;transition:opacity .35s ease}
#ov.on:before{opacity:.4}#ov.on.d2:before{opacity:.68}
#md{position:relative;width:588px;border-radius:28px;background:var(--coral);color:#fff;opacity:0;transition:opacity .25s}
#ov.on #md{opacity:1}
.mtxt{position:absolute;left:30px;right:30px;top:0;display:flex;align-items:center;justify-content:center;text-align:center;font-size:17px;line-height:22px}
.mbtns{position:absolute;left:0;right:0;display:flex;justify-content:center;gap:70px}
/* calendar */
#grid{left:92px;top:129px;width:1112px;height:618px;overflow-y:auto;display:grid;grid-template-columns:repeat(3,312px);grid-auto-rows:156px;gap:34px 80px;align-content:start;scrollbar-width:none;padding:8px}
#grid::-webkit-scrollbar{display:none}
.card{position:relative;border:1px solid var(--ink);border-radius:10px;background:rgba(255,255,255,.6);box-shadow:0 0 4px #000}
.card>*{position:absolute;left:18px;margin:0;white-space:nowrap}
.card h3{top:20px;right:18px;overflow:hidden;text-overflow:ellipsis;font-size:22px;font-weight:600;line-height:28px}
.card .t{top:50px;font-size:16px;font-weight:500;line-height:20px}
.card .au{top:72px;font-size:14px;line-height:18px;color:#555}
.card .st{left:auto;right:15px;top:10px;font-size:13px;line-height:14px;color:var(--coral);display:flex;align-items:center;gap:6px}
.card .st:before{content:"";width:10px;height:10px;border-radius:50%;background:var(--coral)}
.det{top:113px;height:28px;padding:0 20px 0 14px;border-radius:10px;background:var(--ink);color:#fff;font-size:14px;display:flex;align-items:center;gap:10px}
.det:before{content:"";width:7px;height:7px;border-radius:50%;background:#fff}
#nav.ctr{transform:translateX(203px)}
/* settings */
#md.set .mtxt{display:block;left:0;right:0}
.st-t{position:absolute;left:0;right:0;top:20px;text-align:center;font-size:18px;font-weight:500}
.st-r{position:absolute;left:39px;display:flex;align-items:center;gap:62px;height:29px}
.st-l{font-size:14px;font-weight:500;line-height:18px;flex:none;text-align:left}
.vc{display:flex;align-items:center;gap:15px;width:274px;height:29px}.vc img{display:block;flex:none}
#vol{position:relative;width:187px;height:14px;flex:none;touch-action:none;cursor:pointer}
.vl{position:absolute;left:0;top:6px;width:100%;height:2px;background:#6E3C37}
.vk{position:absolute;top:0;left:0;width:14px;height:14px;box-sizing:border-box;border-radius:50%;background:#fff;border:1px solid #6E3C37;transition:transform .25s cubic-bezier(.3,1.7,.5,1),box-shadow .25s,left .25s ease}
#vol.drag .vk{transform:scale(1.55);box-shadow:0 0 0 7px rgba(255,255,255,.28);transition:transform .25s cubic-bezier(.3,1.7,.5,1),box-shadow .25s}
.nr{display:flex;align-items:center;gap:10px;width:252px;height:34px}.nr span{font-size:14px;font-weight:500;white-space:nowrap}
#nBtn{width:36px;height:34px;border-radius:15px;background:rgba(110,60,55,.5);display:grid;place-items:center;flex:none}#nBtn img{width:24px;height:24px}
/* night */
body.night{--ink:#E8E8EE}
body.night #dim{opacity:.82}
body.night .card{background:rgba(24,27,40,.55);box-shadow:0 0 4px rgba(0,0,0,.7)}
body.night .card .au{color:#A9ABB8}
body.night .det{color:#1c1f2a}body.night .det:before{background:#1c1f2a}
body.night .seg button{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.22)}
body.night .seg button.on{background:var(--ink);color:#1c1f2a;border-color:var(--ink)}
body.night .inp{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.22)}
body.night .inp::placeholder{color:#7C7F8E}body.night .dis{background:rgba(255,255,255,.12)}
body.night #nav{background:linear-gradient(135deg,rgba(255,255,255,.16),rgba(255,255,255,.04) 55%,rgba(255,255,255,.1));border-color:rgba(255,255,255,.2);box-shadow:inset 0 1px 0 rgba(255,255,255,.3),inset 0 0 16px rgba(255,255,255,.06),0 6px 24px rgba(0,0,0,.35)}
body.night #nav button svg{fill:rgba(255,255,255,.4)}body.night #nav button.on svg{fill:rgba(255,255,255,.75)}
body.night .logo{filter:brightness(1.45) saturate(1.2)}
.card,.inp{transition:background-color .5s,border-color .5s}.seg button{transition:scale .12s,background-color .4s,border-color .4s,color .4s}
/* სტატუსი */
#hStat{--st:var(--teal);display:flex;align-items:center;gap:6px;font-size:15px;font-weight:500;color:var(--st);transition:color .5s}
#hStat b{font-weight:500}
#hStat .dot{position:relative;flex:none;width:17px;height:17px;border-radius:50%;background:var(--st);filter:drop-shadow(0 0 7px var(--st));animation:beat 1.8s ease-in-out infinite;transition:background-color .5s}
#hStat .dot:before{content:"";position:absolute;inset:0;border-radius:50%;background:var(--st);animation:ring 1.8s ease-out infinite}
@keyframes beat{0%,100%{transform:scale(1)}50%{transform:scale(1.15)}}
@keyframes ring{0%{transform:scale(1);opacity:.55}70%,100%{transform:scale(2.6);opacity:0}}
/* Smart Animate: სახელი + ლოგო მთავარიდან სათაურში გადაედინება */
#sTitle,#sLogo,#sDiv{position:absolute;left:0;top:0}
#sTitle{height:80px;line-height:80px;white-space:nowrap;font-size:68px;font-weight:700;transform:translate(90px,186px);transition:transform .65s cubic-bezier(.65,0,.35,1),font-size .65s cubic-bezier(.65,0,.35,1)}
#sLogo{width:153px;transform:translate(90px,40px);transition:transform .65s cubic-bezier(.65,0,.35,1)}
#sDiv{width:1px;height:42px;background:var(--ink);opacity:0;transform:translate(var(--dx,300px),38px) scaleY(.3);transition:transform .65s cubic-bezier(.65,0,.35,1),opacity .3s}
#frame.hd #sTitle{font-size:32px;transform:translate(85px,19px)}
#frame.hd #sLogo{transform:translate(var(--lx,314px),44px)}
#frame.hd #sDiv{opacity:1;transform:translate(var(--dx,300px),38px) scaleY(1);transition:transform .65s cubic-bezier(.65,0,.35,1),opacity .4s .25s}
/* გვერდების zoom გადასვლა */
.page.on{animation:pgin .5s cubic-bezier(.2,.7,.2,1) both}
.page.out{animation:pgout .2s ease-in both}
@keyframes pgin{from{opacity:0;transform:scale(.95)}to{opacity:1;transform:none}}
@keyframes pgout{to{opacity:0;transform:scale(1.04)}}
#wTog{right:48px;top:463px;width:120px;height:34px;background:rgba(110,60,55,.5);border-radius:10px;color:#fff;font-size:13px;white-space:nowrap}
.fd.in{animation:fdin .4s cubic-bezier(.2,.8,.3,1) both}
@keyframes fdin{from{opacity:0;transform:translateY(16px) scale(.94)}}
.dt-r{position:absolute;left:39px;right:39px;display:flex;align-items:center;gap:20px;height:20px;font-size:14px;line-height:20px}
.dt-l{width:96px;flex:none;font-weight:500}
.dt-v{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#burger .bi{position:relative;display:block;width:30px;height:24px}
#burger .bi i{position:absolute;height:3.5px;border-radius:2px;background:#fff;transition:transform .45s cubic-bezier(.65,0,.35,1),width .45s cubic-bezier(.65,0,.35,1),left .45s cubic-bezier(.65,0,.35,1),opacity .25s}
#burger .b1{left:2px;top:1.25px;width:26px}#burger .b2{left:2px;top:10.25px;width:26px}#burger .b3{left:12px;top:19.25px;width:16px}
#burger.x .b1{transform:translateY(9px) rotate(45deg)}
#burger.x .b2{opacity:0;transform:scaleX(0)}
#burger.x .b3{left:2px;width:26px;transform:translateY(-9px) rotate(-45deg)}
/* QR */
#qr{position:absolute;right:440px;top:26px;width:289px;height:254px;z-index:2;transition:opacity .45s ease,transform .45s cubic-bezier(.65,0,.35,1)}
#qr.gone{opacity:0;transform:scale(.92);pointer-events:none}
.qc{width:100%;height:100%;box-sizing:border-box;border-radius:20px;background:rgba(255,255,255,.92);border:1px solid #fff;box-shadow:0 8px 28px rgba(60,60,100,.14);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;color:#303030;padding:10px}
.qc b{font-size:17px;font-weight:700;line-height:20px}.qc span{font-size:13px;line-height:16px;opacity:.7}.qc img{width:184px;height:184px;margin-top:4px;display:block}
#stage.narrow #qr{top:330px}
#stage.narrow #hTitle{width:var(--tw)!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* booking */
.lab{left:85px;font-size:19px}
.inp{left:415px;width:709px;height:31px;border:1px solid #D4D4D4;border-radius:6px;background:rgba(255,255,255,.8);padding:0 14px;font:inherit;font-size:16px;color:var(--ink);outline:0}
.inp::placeholder{color:#C4C4C4}.inp:focus{border-color:var(--teal)}
.dis{background:#D9D9D9;border:0;display:flex;align-items:center}
.seg{display:flex;gap:9px}.seg button{width:137px;height:31px;border:1px solid #CFCFCF;border-radius:6px;background:rgba(255,255,255,.8);font-size:16px}
.seg button.on{background:var(--ink);border-color:var(--ink);color:#fff}
.rb{width:44px;height:44px;display:grid;place-items:center}
.big{font-size:44px;font-weight:300}
.cta{top:700px;width:180px;height:41px;padding:0}.cta img{display:block}
#bCancel{left:97px}#bOk{left:940px}#bOk:disabled{opacity:.4}              
#warn{left:430px;top:592px;font-size:15px;color:var(--red)}
/* navbar */
#nav{left:233px;top:684px;transition:transform .55s cubic-bezier(.65,0,.35,1);will-change:transform;width:408px;height:65px;border-radius:16px;background:linear-gradient(135deg,rgba(255,255,255,.55),rgba(255,255,255,.18) 55%,rgba(255,255,255,.38));border:1px solid rgba(255,255,255,.8);backdrop-filter:blur(18px) saturate(1.5);-webkit-backdrop-filter:blur(18px) saturate(1.5);box-shadow:inset 0 1px 0 rgba(255,255,255,.95),inset 0 -1px 0 rgba(255,255,255,.4),inset 0 0 16px rgba(255,255,255,.35),0 6px 24px rgba(40,40,90,.10);display:flex;align-items:flex-end;padding-left:24px;gap:13px}
#nav button{height:63px;display:flex;align-items:center;justify-content:center;gap:12px;font-size:17px;font-weight:700;border-bottom:2px solid transparent;color:var(--ink)}
#nav button svg{fill:rgba(0,0,0,.3);transition:fill .35s}
#ind{position:absolute;left:24px;top:0;height:63px;width:72px;overflow:hidden;pointer-events:none;transition:left .5s cubic-bezier(.65,0,.35,1),width .5s cubic-bezier(.65,0,.35,1)}
#ind:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(217,217,217,0),#148380);filter:blur(12.4px);border-radius:16px}
#ind:after{content:'';position:absolute;left:0;right:0;bottom:0;border-bottom:3px solid #148380}
#nav button.on svg{fill:rgba(0,0,0,.45)}
#toast{position:absolute;left:50%;bottom:120px;transform:translateX(-50%);background:var(--ink);color:#fff;padding:12px 28px;border-radius:12px;font-size:17px;opacity:0;transition:opacity .3s;pointer-events:none;z-index:9}
#toast.on{opacity:1}
</style></head><body>
<div id="stage">
<div id="bg"><i class="blob" style="left:-420px;top:500px;width:840px;height:600px;--c:#FFC6DA;--d:38s;--x:300px;--y:-260px;--s:1.15;animation-delay:0s"></i><i class="blob" style="left:-380px;top:216px;width:760px;height:720px;--c:#FFE6D2;--d:44s;--x:380px;--y:-120px;--s:1.1;animation-delay:-12s"></i><i class="blob" style="left:-16px;top:520px;width:800px;height:560px;--c:#DCD0F7;--d:40s;--x:-200px;--y:-240px;--s:1.2;animation-delay:-20s"></i><i class="blob" style="left:286px;top:500px;width:760px;height:600px;--c:#B9D8E6;--d:46s;--x:260px;--y:-300px;--s:1.1;animation-delay:-8s"></i><i class="blob" style="left:516px;top:116px;width:760px;height:760px;--c:#CFD8FF;--d:52s;--x:-420px;--y:200px;--s:1.1;animation-delay:-30s"></i><i class="blob" style="left:664px;top:540px;width:720px;height:520px;--c:#F6ADA3;--d:36s;--x:-300px;--y:-240px;--s:1.2;animation-delay:-5s"></i><i id="dim"></i></div>

<div id="frame">
<!-- ============ მთავარი ============ -->
<section class="page on" id="p-home">
    <div class="a" style="left:90px;top:140px;font-size:22px" >შეხვედრის ოთახი</div>
  <div class="a" style="right:558px;top:140px;font-size:22px">მაგიდა: 1 / სკამი: #</div>
    <div class="a rule" style="left:90px;top:306px;width:632px"></div>
  <div class="a" id="hRow" style="left:90px;top:352px;display:flex;align-items:center;gap:27px">
    <div class="badge" id="hBadge">ახლანდელი შეხვედრა</div>
    <div id="hStat"><i class="dot"></i><b>თავისუფალია</b></div>
  </div>
  <div class="a" id="hTitle" style="left:90px;top:424px;font-size:34px;font-weight:500;line-height:1.3;width:640px"></div>
  <div class="a" id="hTime" style="left:90px;top:482px;font-size:34px;font-weight:300"></div>
  <div class="a" id="hAuthor" style="left:90px;top:552px;font-size:25px"></div>
  <div class="a" id="hKind" style="left:90px;top:602px;font-size:14px">Teams Meeting / Room Meeting</div>
</section>

<!-- ============ კალენდარი ============ -->
<section class="page" id="p-cal">
    <div class="a" id="grid"></div>
</section>

<!-- ============ დარეზერვება ============ -->
<section class="page" id="p-book">
    <div class="a" id="bDate" style="right:156px;top:40px;font-size:16px;text-align:right"></div>
  <div class="a" id="bClock" style="right:156px;top:62px;font-size:36px;text-align:right;font-weight:400"></div>

  <div class="a lab mid" style="top:144px">შეხვედრის დასახელება:</div>
  <input class="a inp mid" id="fTitle" style="top:144px" placeholder="შეხვედრის დასახელება" maxlength="80">
  <div class="a lab mid" style="top:205px">სტატუსი:</div>
  <div class="a seg mid" id="fStatus" style="left:415px;top:205px"><button class="on" data-v="normal">ნორმალური</button><button data-v="urgent">ურგენტული</button></div>
  <div class="a lab mid" style="top:266px">ავტორი:</div>
  <div class="a inp dis mid" style="top:266px">Default ავტორი</div>
  <div class="a lab mid" style="top:327px">სტუმრები:</div>
