<script>
const ASSETS = {"minus-on": "data:image/svg+xml;base64,", "minus-off": "data:image/svg+xml;base64,", "plus-on": "data:image/svg+xml;base64,", "plus-off": "data:image/svg+xml;base64,", "weather-sunny": "data:image/svg+xml;base64,", "weather-windy": "data:image/svg+xml;base64,", "weather-rainy": "data:image/svg+xml;base64,", "weather-snowy": "data:image/svg+xml;base64,"};
/* ===== კონფიგურაცია ===== */
const ROOMS = {   // TODO: დანარჩენი 3 ოთახის სახელი / ფერი / მეილი (არჩევა: index.html?room=room2)
  gulisqari: {name: 'გულისკარი', email: 'guliskari@ip13.onmicrosoft.com', color: '#FA6E5F'},
  room2: {name: 'ოთახი 2', email: 'room2@company.com', color: '#FA6E5F'},
  room3: {name: 'ოთახი 3', email: 'room3@company.com', color: '#FA6E5F'},
  room4: {name: 'ოთახი 4', email: 'room4@company.com', color: '#FA6E5F'}
};
const ROOM = ROOMS[new URLSearchParams(location.search).get('room')] || ROOMS.gulisqari;
const CONFIG = {
  source: 'mr365',                       // 'mock' | 'graph'
  apiBase: '/api',                      // თქვენი ბექენდ-პროქსი Outlook-ისთვის
  room: ROOM.email,                     // OUTLOOK: ოთახის mailbox
  itEmail: 'clinics_it_support@evex.ge', canFuture: false, itWebhook: '',            // IT მოთხოვნების მისამართი
  tz: 'Asia/Tbilisi',
  refreshSec: 60
};

/* ===== მონაცემები (OUTLOOK ინტეგრაცია აქ) ===== */
const MIN = 60000, now0 = Date.now();
const mockEvents = (() => {
  const free = location.search.includes('free');           // ?free = თავისუფალი ოთახი
  const o = free ? 90 : -30;
  return [0, 120, 180, 270, 360, 450, 540, 630, 720, 810].map((d, i) => ({
    title: i % 2 ? 'Project Sync' : 'IT Meeting',
    start: new Date(now0 + (o + d) * MIN), end: new Date(now0 + (o + d + (i ? 60 : 90)) * MIN),
    author: 'სახელი გვარი', kind: 'Teams Meeting / Room Meeting'
  }));
})();
const EVX = {   // Meeting Room 365-თან ხიდი: მშობელი გვერდი კითხულობს მის კალენდარს და გვიგზავნის postMessage-ით
  evs: [], local: [], pending: {},
  events() { const now = Date.now(); this.local = this.local.filter(l => l.until > now); return this.evs.concat(this.local.filter(l => !this.evs.some(r => Math.abs(r.start - l.start) < 60000))); },
  send(type, data) { return new Promise(res => { const id = Math.random().toString(36).slice(2); this.pending[id] = res; parent.postMessage({evx: type, id, ...data}, '*');
    setTimeout(() => { if (this.pending[id]) { delete this.pending[id]; res(false); } }, 6000); }); }
};
addEventListener('message', e => {
  const m = e.data || {};
  if (m.evx === 'events') { EVX.evs = (m.events || []).map(x => ({...x, start: new Date(x.start), end: new Date(x.end)})); load(); }
  if (m.evx === 'reply' && EVX.pending[m.id]) { EVX.pending[m.id](m.ok); delete EVX.pending[m.id]; }
});
if (CONFIG.source === 'mr365') parent.postMessage({evx: 'ready'}, '*');
const API = {
  async list() {
    if (CONFIG.source === 'mr365') return EVX.events();
    if (CONFIG.source === 'graph') {
      // OUTLOOK: ბექენდი იძახებს Microsoft Graph-ს:
      // GET /users/{room}/calendarView?startDateTime=..&endDateTime=..  (დღევანდელი დღე, თბილისის დრო)
      const r = await fetch(`${CONFIG.apiBase}/events?room=${encodeURIComponent(CONFIG.room)}`);
      return (await r.json()).map(x => ({
        title: x.subject, start: new Date(x.start), end: new Date(x.end),
        author: x.organizer?.emailAddress?.name || '', kind: x.isOnlineMeeting ? 'Teams Meeting' : 'Room Meeting'
      }));
    }
    return mockEvents;
  },
  async create(ev) {
    if (CONFIG.source === 'mr365') {   // MR365-ის ჩაშენებული "ახლავე დაჯავშნა" (15/30 წთ)
      if (!await EVX.send('book', {minutes: Math.round((ev.end - ev.start) / MIN)})) throw new Error('book failed');
      EVX.local.push({...ev, until: Date.now() + 90000}); return;
    }
    if (CONFIG.source === 'graph') {
      // OUTLOOK: POST /users/{room}/events  (subject, start, end, importance: urgent ? 'high':'normal')
      await fetch(`${CONFIG.apiBase}/events`, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({room: CONFIG.room, ...ev})});
    } else mockEvents.push(ev), mockEvents.sort((a,b)=>a.start-b.start);
  },
  async requestIT() {
    if (CONFIG.itWebhook) {   // მაგ. Power Automate HTTP trigger, რომელიც IT-ს მეილზე წერილს აგზავნის
      await fetch(CONFIG.itWebhook, {method: 'POST', mode: 'no-cors', headers: {'Content-Type': 'text/plain'}, body: JSON.stringify({room: ROOM.name, email: ROOM.email, to: CONFIG.itEmail, at: new Date().toISOString()})}); return;
    }
    if (CONFIG.source === 'mr365') throw new Error('IT webhook is not configured');
    if (CONFIG.source === 'graph') {
      // MAIL: ბექენდი აგზავნის წერილს IT-ის მეილზე (Graph: POST /users/{room}/sendMail) — "ოთახს სჭირდება დახმარება"
      const r = await fetch(`${CONFIG.apiBase}/it-request`, {method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({room: ROOM.name, from: ROOM.email, to: CONFIG.itEmail, at: new Date().toISOString()})});
      if (!r.ok) throw new Error('it-request failed');
    } else console.log('IT request (mock):', ROOM.name, '->', CONFIG.itEmail);
  }
};

/* ===== დრო (თბილისი) ===== */
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const fmtHM = d => new Intl.DateTimeFormat('en-GB',{timeZone:CONFIG.tz,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);
const esc = x => String(x ?? '').replace(/[&<>"]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));
const GE_DAYS = ['კვირა','ორშაბათი','სამშაბათი','ოთხშაბათი','ხუთშაბათი','პარასკევი','შაბათი'];
const GE_SHORT = ['კვი','ორშ','სამ','ოთხ','ხუთ','პარ','შაბ'];
const fmtDate = d => {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:CONFIG.tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d).map(x=>[x.type,x.value]));
  const wd = GE_DAYS[{Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6}[new Intl.DateTimeFormat('en-US',{timeZone:CONFIG.tz,weekday:'short'}).format(d)]];
  return `${wd}, ${p.month}/${p.day}/${p.year}`;
};

/* ===== მდგომარეობა ===== */
let events = [], page = 'home';
const B = {dur: 15, guests: 1, status: 'normal', slot: null};
const current = () => events.find(e => e.start <= Date.now() && Date.now() < e.end);
const upcoming = () => events.filter(e => e.end > Date.now());

/* ===== რენდერი ===== */
function renderHome() {
  const c = current(), n = c || upcoming()[0], b = $('#hBadge');   // თავისუფალია -> ვაჩვენებთ შემდეგ შეხვედრას
  b.textContent = c ? 'ახლანდელი შეხვედრა' : 'შემდეგი შეხვედრა'; b.style.display = n ? '' : 'none';
  $('#hStat').style.setProperty('--st', c ? 'var(--coral)' : 'var(--teal)');
  $('#hStat b').textContent = c ? 'დაკავებულია' : 'თავისუფალია';
  $('#hTitle').textContent = n ? n.title : 'დღეს შეხვედრები აღარ არის';
  $('#hTime').textContent = n ? `${fmtHM(n.start)} - ${fmtHM(n.end)}` : '';
  $('#hAuthor').textContent = n ? 'ავტორი: ' + n.author : '';
  $('#hKind').textContent = n ? n.kind : '';
}
function cardHTML(e, extra) {
  return `<div class="sc"><h4>${esc(e.title)}</h4>${extra}<p>${fmtHM(e.start)}-${fmtHM(e.end)}</p><small>ავტორი: ${esc(e.author)}</small></div>`;
}
function renderSide() {
  const c = current();
  $('#sideList').innerHTML = upcoming().map(e => {
    const h = cardHTML(e, e === c ? '<em>(ახლა)</em>' : '');
    return h;
  }).join('');
}
function renderCal() {
  $('#grid').innerHTML = events.map((e, i) => `<div class="card"><span class="st">დაკავებულია</span>
    <h3>${esc(e.title)}</h3><div class="t">${fmtHM(e.start)}-${fmtHM(e.end)}</div><div class="au">ავტორი: ${esc(e.author)}</div>
    <button class="det" data-i="${i}">დეტალები</button></div>`).join('');
}
const busy = (s, e) => events.some(x => x.start < e && x.end > s);
function times() {
  if (B.slot && B.slot <= Date.now()) B.slot = null;
  const s0 = new Date(Math.floor(Date.now() / MIN) * MIN), nowBusy = busy(s0, new Date(+s0 + B.dur * MIN));
  const s = B.slot && nowBusy ? new Date(B.slot) : s0, e = new Date(+s + B.dur * MIN);
  return {s, e, conflict: busy(s, e), nowBusy};
}
// უახლოესი თავისუფალი დროები არჩეული ხანგრძლივობისთვის
function slots(dur) {
  const out = []; let t = Math.ceil(Date.now() / MIN) * MIN; const end = t + 12 * 3600000;
  while (out.length < 4 && t < end) {
    const e = t + dur * MIN, c = events.find(x => x.start < e && x.end > t);
    if (c) t = Math.max(t + MIN, Math.ceil(+c.end / MIN) * MIN); else { out.push(t); t += dur * MIN; }
  }
  return out;
}
let slotSig = '';
function renderSlots(show) {
  const row = $('#fSlots'); row.style.display = $('#slotLab').style.display = show ? '' : 'none';
  if (!show) { slotSig = ''; return; }
  const list = slots(B.dur), sig = list.join() + '|' + B.slot; if (sig === slotSig) return; slotSig = sig;
  row.innerHTML = list.map(t => `<button data-t="${t}" class="${t === B.slot ? 'on' : ''}">${fmtHM(new Date(t))}–${fmtHM(new Date(t + B.dur * MIN))}</button>`).join('') || '<span style="font-size:15px">დღეს თავისუფალი დრო აღარ არის</span>';
}
function renderBook() {
  const {s, e, conflict, nowBusy} = times();
  $('#tFrom').textContent = fmtHM(s); $('#tTo').textContent = fmtHM(e);
  $('#bDate').textContent = fmtDate(new Date()); $('#bClock').textContent = fmtHM(new Date());
  $('#gNum').textContent = B.guests;
  $('#gMinus img').src = ASSETS['minus-' + (B.guests > 1 ? 'on' : 'off')];
  $('#gPlus img').src = ASSETS['plus-' + (B.guests < 50 ? 'on' : 'off')];
  $('#bOk').disabled = conflict;
  $('#warn').textContent = nowBusy && !B.slot ? (CONFIG.canFuture ? 'ოთახი ამ დროს დაკავებულია — აირჩიეთ სხვა დრო' : 'ოთახი ამ დროს დაკავებულია') : '';
  renderSlots(nowBusy && CONFIG.canFuture);
}

function tick() {
  const d = new Date();
  $('#clock').textContent = fmtHM(d); $('#sdate').textContent = fmtDate(d);
  const [wd, dt] = fmtDate(d).split(', '); $('#sdate2').innerHTML = `<b>${wd}</b>, ${dt}`;
  if (page === 'home') renderHome();
  if (page === 'book') renderBook();
  renderSide();
}
const rnd = d => new Date(Math.round(+d / MIN) * MIN);
async function load() { try { events = (await API.list()).map(x => ({...x, start: rnd(x.start), end: rnd(x.end)})); } catch (e) { console.error(e); } renderCal(); tick(); }

/* ===== ნავიგაცია ===== */
function go(p) {
  page = p;
  showPage(p); $('#frame').classList.toggle('hd', p !== 'home'); $('#qr').classList.toggle('gone', p !== 'home');
  $$('#nav button').forEach(b => b.classList.toggle('on', b.dataset.go === p));
  const side = $('#side'); side.classList.remove('open'); $('#burger').classList.remove('x'); side.classList.toggle('full', p === 'home');
  $('#burger').style.display = p === 'home' ? 'none' : '';
  moveInd(); navPos();
  tick();
}
$$('#nav button').forEach(b => b.onclick = () => go(b.dataset.go));
function setOpen(v) { $('#side').classList.toggle('open', v); $('#burger').classList.toggle('x', v); navPos(); }
$('#burger').onclick = () => setOpen(!$('#side').classList.contains('open'));
document.addEventListener('pointerdown', e => { if ($('#side').classList.contains('open') && !e.target.closest('#side, #ov')) setOpen(false); });

/* ===== დარეზერვება ===== */
function seg(id, key, cast) {
  $$(`${id} button`).forEach(b => b.onclick = () => {
    $$(`${id} button`).forEach(x => x.classList.toggle('on', x === b));
    B[key] = cast ? +b.dataset.v : b.dataset.v; if (key === 'dur') B.slot = null; renderBook();
  });
}
seg('#fStatus', 'status'); seg('#fDur', 'dur', true);
$('#fSlots').onclick = ev => { const b = ev.target.closest('button'); if (!b) return; const t = +b.dataset.t; B.slot = B.slot === t ? null : t; slotSig = ''; renderBook(); };
const bump = () => $('#gNum').animate([{transform: 'translateY(-50%) scale(1.3)', opacity: .5}, {transform: 'translateY(-50%) scale(1)', opacity: 1}], {duration: 240, easing: 'cubic-bezier(.2,.8,.3,1)'});
$('#gMinus').onclick = () => { if (B.guests > 1) { B.guests--; renderBook(); bump(); } };
$('#gPlus').onclick = () => { if (B.guests < 50) { B.guests++; renderBook(); bump(); } };
function toast(t) { const x = $('#toast'); x.textContent = t; x.classList.add('on'); setTimeout(() => x.classList.remove('on'), 2200); }
function resetForm() {
  Object.assign(B, {dur: 15, guests: 1, status: 'normal', slot: null}); $('#fTitle').value = '';
  $$('#fStatus button').forEach((b, i) => b.classList.toggle('on', i === 0));
  $$('#fDur button').forEach((b, i) => b.classList.toggle('on', i === 0));
}
$('#bCancel').onclick = () => { resetForm(); go('home'); };   // TODO: დადასტურების ფრეიმი
$('#bOk').onclick = async () => {
  const {s, e, conflict} = times(); if (conflict) return;
  try { await API.create({title: $('#fTitle').value.trim() || 'შეხვედრა', start: s, end: e, author: 'Default ავტორი',
    kind: 'Room Meeting', urgent: B.status === 'urgent', guests: B.guests}); }
  catch (err) { console.error(err); return modal('ვერ დაიჯავშნა.<br>სცადეთ თავიდან.', [['გასაგებია']], 117, 186, 295); }
  const mins = Math.round((e - s) / MIN);
  await load(); resetForm(); go('home');
  modal(`ოთახი დაიჯავშნა თქვენ მიერ<br>${mins} წუთით!`, [['გასაგებია']], 117, 186, 295);
};

let swapT;
function showPage(p) {   // ძველი გვერდი ქრება (zoom), ახალი ჩნდება (zoom), სახელი და ლოგო კი მოძრაობს
  clearTimeout(swapT); $$('.page').forEach(x => x.classList.remove('out'));
  const cur = $('.page.on'), nxt = $('#p-' + p); if (cur === nxt) return;
  const swap = () => $$('.page').forEach(x => x.classList.toggle('on', x === nxt));
  if (!cur) return swap();
  cur.classList.add('out'); swapT = setTimeout(() => { cur.classList.remove('out'); swap(); }, 200);
}
